mapper.select:
SELECT ${groupName} AS dimension,
SUM(order_fee * currency_rate) AS salesAmount
FROM dmp_order_info AS doi
WHERE doi.${groupName} IS NOT NULL

    AND doi.platform_create_time >= #{params.startTime}


    AND doi.platform_create_time <= #{params.endTime}

/*部门*/

    AND doi.dept_id IN

        #{deptId}


/*平台*/

    AND doi.platform_name IN

        #{platform}


/*站点*/

    AND doi.site IN

        #{site}



/*店铺*/

    AND doi.shop_no IN

        #{shopNo}


/*用户id*/

    AND doi.charge_id IN

        #{userId}




    #{params.param}

GROUP BY doi.${groupName}
